 const fields=[['area','Catchment area, A','ha',0],['ari','Return period, ARI','years',2,100],['lo','Overland flow length, Lₒ','m',0],['horton','Horton roughness, n','',0],['so','Surface slope, Sₒ','%',0],['lch','Channel flow length, Lch','m',0],['vtravel','Estimated travel velocity, V','m/s',0],['c','Runoff coefficient, C','',0,1],['gradient','Longitudinal slope, 1 : N','N',0],['depth','Overall depth, d','m',0.05],['base','Base width, b','m',0],['sideSlope','Side slope, X H : 1V','X',2],['manning','Manning roughness, n','',0],['lambda','Constant λ','',0],['kappa','Constant κ','',0],['theta','Constant θ','hours',0],['eta','Constant η','',0]];
