 function update(){const r=calculate(draft),designerReady=Boolean(String(draft.designer||'').trim()),missing=[...(!designerReady?['Prepared by']:[]),...(r.valid?[]:r.errors)];document.querySelector('#ed-dialog-ari').textContent='Fixed 2-year ARI: refer to the Minor System column.';document.querySelector('#ed-validation').textContent=missing.length?`Complete or correct: ${missing.join(', ')}.`:'';document.querySelector('#ed-print').disabled=!r.valid||!designerReady;for(const [key] of fields){const el=document.querySelector('#ed-'+key);if(el)el.setAttribute('aria-invalid',String(!r.valid&&r.errors.includes(fields.find(f=>f[0]===key)[1])))}document.querySelector('#ed-results').innerHTML=r.valid?`<div class="drain-metrics"><div><span>Qpeak</span><strong>${f(r.peak,3)} <small>m³/s</small></strong></div><div><span>Qallow · Template</span><strong>${f(r.q,3)} <small>m³/s</small></strong></div><div><span>Velocity · Template</span><strong>${f(r.v,3)} <small>m/s</small></strong></div><div><span>Time of concentration</span><strong>${f(r.tc)} <small>min</small></strong></div></div><p class="check-line ${r.capacityOk?'':'check-fail'}">Template capacity: ${r.capacityOk?'OK':'NOT OK'} · Qallow &gt; Qpeak</p><p class="check-line ${r.velocityOk?'':'check-fail'}">Template velocity: ${r.velocityOk?'OK':'NOT OK'} · V &lt; 2.0 m/s</p>${r.warnings.map(x=>'<p class="check-fail">'+esc(x)+'</p>').join('')}`:'<p>Complete the inputs to view the calculation results.</p>';document.querySelector('#ed-section').innerHTML=sectionDiagram(r);document.querySelector('#ed-report').innerHTML=report(r);const status=!r.valid||!designerReady?'incomplete':r.capacityOk&&r.velocityOk&&!r.warnings.length?'passed':'review';root.dispatchEvent(new CustomEvent('nadi:module-status',{detail:{key:'0/0',status}}));}
